exercises.reference:
def is_leap(year):
    """Gregorian calendar: divisible by 4, except centuries, except every 400 years."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def test_ordinary_years():
    assert is_leap(2024)
    assert not is_leap(2023)


def test_centuries_are_not_leap_years():
    assert not is_leap(1900)
    assert not is_leap(2100)


def test_every_400_years_is_a_leap_year():
    assert is_leap(2000)
    assert is_leap(2400)
